using System.Data.Common;
using System.Globalization;

using Depot.Data;
using Depot.Models;

namespace Depot.Repositories;

public sealed class FinanceAccountsReceivableRepository : DatabaseRepository
{
	private const string OpenItemColumns = "oi.Id,oi.Version,oi.LegalEntityId,oi.AccountingBookId,oi.CustomerId,c.Name,oi.Kind,oi.SourceType,oi.SourceId,oi.SourceReference,oi.DocumentDate,oi.DueDate,oi.CurrencyCode,oi.OriginalAmount,oi.RemainingAmount,oi.JournalEntryId,oi.OperationId,oi.IsVoided,oi.CreatedAtUtc,oi.CreatedByUserId";
	private const string PaymentColumns = "Id,Version,OperationId,RequestHash,CustomerId,CurrencyCode,PaymentDate,Amount,Reference,Description,OpenItemId,JournalEntryId,CreatedAtUtc,CreatedByUserId,IsReversed,ReversalOperationId,ReversalJournalEntryId,ReversedAtUtc,ReversedByUserId";
	private const string WriteOffColumns = "Id,Version,OperationId,RequestHash,OpenItemId,Amount,PostingDate,Reason,JournalEntryId,CreatedAtUtc,CreatedByUserId,IsReversed,ReversalOperationId,ReversalJournalEntryId,ReversedAtUtc,ReversedByUserId";

	public FinanceAccountsReceivableRepository(DatabaseAccess database) : base(database) { }

	public Task<FinanceReceivablesConfiguration?> GetConfigurationAsync(CancellationToken cancellationToken = default) =>
		Database.QuerySingleOrDefaultAsync("SELECT Id,Version,LegalEntityId,FiscalCalendarId,InvoicePostingProfileId,CreditNotePostingProfileId,PaymentPostingProfileId,WriteOffPostingProfileId,IsActive FROM FinanceReceivablesConfigurations ORDER BY Id;", ReadConfiguration, cancellationToken);

	public Task<PageResult<FinanceReceivableOpenItem>> SearchOpenItemsAsync(string? searchText, bool includeSettled, int pageNumber, int pageSize, CancellationToken cancellationToken)
	{
		var filters = new List<string> { "oi.IsVoided=0" };
		var parameters = new List<DatabaseParameter>();
		if (!includeSettled) filters.Add("oi.RemainingAmount>0");
		if (!string.IsNullOrWhiteSpace(searchText))
		{
			filters.Add("(c.Name LIKE $Search OR oi.SourceReference LIKE $Search OR oi.SourceId LIKE $Search)");
			parameters.Add(Parameter("$Search", $"%{searchText.Trim()}%"));
		}
		var from = "FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId";
		var where = $"WHERE {string.Join(" AND ", filters)}";
		return Database.QueryPageAsync($"SELECT {OpenItemColumns} {from} {where} ORDER BY oi.DueDate,oi.Id", $"SELECT COUNT(*) {from} {where};", ReadOpenItem, pageNumber, pageSize, cancellationToken, parameters.ToArray());
	}

	public Task<FinanceReceivableOpenItem?> GetOpenItemAsync(long id, CancellationToken cancellationToken = default) =>
		Database.QuerySingleOrDefaultAsync($"SELECT {OpenItemColumns} FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId WHERE oi.Id=$Id;", ReadOpenItem, cancellationToken, Parameter("$Id", id));

	public Task<FinanceReceivablePayment?> GetPaymentAsync(long id, CancellationToken cancellationToken = default) =>
		Database.QuerySingleOrDefaultAsync($"SELECT {PaymentColumns} FROM FinanceReceivablePayments WHERE Id=$Id;", ReadPayment, cancellationToken, Parameter("$Id", id));

	public Task<FinanceReceivableWriteOff?> GetWriteOffAsync(long id, CancellationToken cancellationToken = default) =>
		Database.QuerySingleOrDefaultAsync($"SELECT {WriteOffColumns} FROM FinanceReceivableWriteOffs WHERE Id=$Id;", ReadWriteOff, cancellationToken, Parameter("$Id", id));

	public Task<IReadOnlyList<FinanceReceivableAgingRow>> GetAgingRowsAsync(DateOnly asOfDate, CancellationToken cancellationToken = default) =>
		Database.QueryAsync(
			"SELECT oi.CustomerId,c.Name,oi.CurrencyCode,oi.DueDate,oi.RemainingAmount,oi.Kind FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId WHERE oi.IsVoided=0 AND oi.RemainingAmount>0 AND oi.DocumentDate<=$AsOfDate ORDER BY c.Name,oi.CurrencyCode,oi.DueDate,oi.Id;",
			reader => new FinanceReceivableAgingRow(reader.GetInt64(0), reader.GetString(1), new CurrencyCode(reader.GetString(2)), ReadDateOnly(reader, 3), ReadDecimal(reader, 4), (FinanceReceivableOpenItemKind)Convert.ToInt32(reader.GetValue(5), CultureInfo.InvariantCulture)),
			cancellationToken,
			Parameter("$AsOfDate", asOfDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)));

	public Task<IReadOnlyList<FinanceCustomerStatementRow>> GetCustomerStatementAsync(long customerId, CurrencyCode currency, DateOnly fromDate, DateOnly toDate, CancellationToken cancellationToken = default) =>
		Database.QueryAsync(
			"SELECT DocumentDate,Kind,COALESCE(SourceReference,SourceId),SourceType,CurrencyCode,OriginalAmount,RemainingAmount FROM FinanceReceivableOpenItems WHERE CustomerId=$CustomerId AND CurrencyCode=$Currency AND DocumentDate>=$FromDate AND DocumentDate<=$ToDate AND IsVoided=0 ORDER BY DocumentDate,Id;",
			reader =>
			{
				var kind = (FinanceReceivableOpenItemKind)Convert.ToInt32(reader.GetValue(1), CultureInfo.InvariantCulture);
				var amount = ReadDecimal(reader, 5);
				return new FinanceCustomerStatementRow(ReadDateOnly(reader, 0), kind.ToString(), reader.GetString(2), reader.GetString(3), new CurrencyCode(reader.GetString(4)), kind == FinanceReceivableOpenItemKind.Invoice ? amount : 0m, kind == FinanceReceivableOpenItemKind.Invoice ? 0m : amount, ReadDecimal(reader, 6));
			},
			cancellationToken,
			Parameter("$CustomerId", customerId),
			Parameter("$Currency", currency.Value),
			Parameter("$FromDate", fromDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)),
			Parameter("$ToDate", toDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)));

	public async Task<IReadOnlyList<FinanceDunningPolicy>> GetDunningPoliciesAsync(CancellationToken cancellationToken = default)
	{
		var policies = await Database.QueryAsync("SELECT Id,Version,LegalEntityId,Code,Name,IsActive FROM FinanceDunningPolicies ORDER BY Code;", ReadPolicy, cancellationToken);
		var result = new List<FinanceDunningPolicy>(policies.Count);
		foreach (var policy in policies) result.Add(policy with { Levels = await LoadPolicyLevelsAsync(policy.Id, cancellationToken) });
		return result;
	}

	public async Task<FinanceDunningRun?> GetDunningRunAsync(long id, CancellationToken cancellationToken = default)
	{
		var run = await Database.QuerySingleOrDefaultAsync("SELECT Id,OperationId,RequestHash,PolicyId,AsOfDate,CreatedAtUtc,CreatedByUserId FROM FinanceDunningRuns WHERE Id=$Id;", ReadDunningRun, cancellationToken, Parameter("$Id", id));
		return run is null ? null : run with { Lines = await LoadRunLinesAsync(id, cancellationToken) };
	}

