	internal Task<FinanceReceivablesConfiguration?> GetConfigurationAsync(DatabaseTransactionContext transaction, long id, CancellationToken cancellationToken) => transaction.Session.QuerySingleOrDefaultAsync("SELECT Id,Version,LegalEntityId,FiscalCalendarId,InvoicePostingProfileId,CreditNotePostingProfileId,PaymentPostingProfileId,WriteOffPostingProfileId,IsActive FROM FinanceReceivablesConfigurations WHERE Id=$Id;", ReadConfiguration, cancellationToken, Parameter("$Id", id));
	internal Task<long> CreateConfigurationAsync(DatabaseTransactionContext transaction, FinanceReceivablesConfiguration value, CancellationToken cancellationToken) => transaction.Session.InsertAsync("INSERT INTO FinanceReceivablesConfigurations (Version,LegalEntityId,FiscalCalendarId,InvoicePostingProfileId,CreditNotePostingProfileId,PaymentPostingProfileId,WriteOffPostingProfileId,IsActive) VALUES (1,$LegalEntityId,$FiscalCalendarId,$InvoiceProfile,$CreditProfile,$PaymentProfile,$WriteOffProfile,$IsActive);", cancellationToken, ConfigurationParameters(value));
	internal Task<int> UpdateConfigurationAsync(DatabaseTransactionContext transaction, FinanceReceivablesConfiguration value, long expectedVersion, CancellationToken cancellationToken) => transaction.Session.ExecuteAsync("UPDATE FinanceReceivablesConfigurations SET Version=Version+1,LegalEntityId=$LegalEntityId,FiscalCalendarId=$FiscalCalendarId,InvoicePostingProfileId=$InvoiceProfile,CreditNotePostingProfileId=$CreditProfile,PaymentPostingProfileId=$PaymentProfile,WriteOffPostingProfileId=$WriteOffProfile,IsActive=$IsActive WHERE Id=$Id AND Version=$ExpectedVersion;", cancellationToken, ConfigurationParameters(value).Append(Parameter("$Id", value.Id)).Append(Parameter("$ExpectedVersion", expectedVersion)).ToArray());
