	internal Task<IReadOnlyList<FinanceAccountingPeriodRecord>> FindOpenPeriodsAsync(DatabaseTransactionContext transaction, Guid fiscalCalendarId, DateOnly date, CancellationToken cancellationToken) => transaction.Session.QueryAsync("SELECT Id,StartDate,EndDate,Status FROM FinanceAccountingPeriods WHERE FiscalCalendarId=$CalendarId AND StartDate<=$Date AND EndDate>=$Date AND Status=0 ORDER BY StartDate,Id;", reader => new FinanceAccountingPeriodRecord(Guid.Parse(reader.GetString(0)), ReadDateOnly(reader, 1), ReadDateOnly(reader, 2), (AccountingPeriodStatus)Convert.ToInt32(reader.GetValue(3), CultureInfo.InvariantCulture)), cancellationToken, Parameter("$CalendarId", fiscalCalendarId.ToString("D")), Parameter("$Date", date.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)));
	internal Task<FinanceReceivableOpenItem?> FindOpenItemBySourceAsync(DatabaseTransactionContext transaction, string sourceType, string sourceId, CancellationToken cancellationToken) => transaction.Session.QuerySingleOrDefaultAsync($"SELECT {OpenItemColumns} FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId WHERE oi.SourceType=$SourceType AND oi.SourceId=$SourceId;", ReadOpenItem, cancellationToken, Parameter("$SourceType", sourceType), Parameter("$SourceId", sourceId));

	internal async Task<FinanceReceivableOpenItem?> LockOpenItemAsync(DatabaseTransactionContext transaction, long id, CancellationToken cancellationToken)
	{
		await transaction.Session.ExecuteAsync("UPDATE FinanceReceivableOpenItems SET Version=Version WHERE Id=$Id;", cancellationToken, Parameter("$Id", id));
		return await transaction.Session.QuerySingleOrDefaultAsync($"SELECT {OpenItemColumns} FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId WHERE oi.Id=$Id;", ReadOpenItem, cancellationToken, Parameter("$Id", id));
	}

