	internal Task<int> CreateAllocationAsync(DatabaseTransactionContext transaction, FinanceReceivableAllocation value, CancellationToken cancellationToken) => transaction.Session.ExecuteAsync("INSERT INTO FinanceReceivableAllocations (OperationId,DebitOpenItemId,CreditOpenItemId,Amount,AllocationDate,CreatedAtUtc,CreatedByUserId) VALUES ($OperationId,$DebitId,$CreditId,$Amount,$Date,$CreatedAtUtc,$CreatedByUserId);", cancellationToken, Parameter("$OperationId", value.OperationId.ToString("D")), Parameter("$DebitId", value.DebitOpenItemId), Parameter("$CreditId", value.CreditOpenItemId), Parameter("$Amount", value.Amount), Parameter("$Date", value.AllocationDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)), Parameter("$CreatedAtUtc", value.CreatedAtUtc.ToString("O", CultureInfo.InvariantCulture)), Parameter("$CreatedByUserId", value.CreatedByUserId));
