	internal Task<FinanceReceivablePayment?> FindPaymentByOperationAsync(DatabaseTransactionContext transaction, Guid operationId, CancellationToken cancellationToken) => transaction.Session.QuerySingleOrDefaultAsync($"SELECT {PaymentColumns} FROM FinanceReceivablePayments WHERE OperationId=$OperationId;", ReadPayment, cancellationToken, Parameter("$OperationId", operationId.ToString("D")));
	internal async Task<FinanceReceivablePayment?> LockPaymentAsync(DatabaseTransactionContext transaction, long id, CancellationToken cancellationToken) { await transaction.Session.ExecuteAsync("UPDATE FinanceReceivablePayments SET Version=Version WHERE Id=$Id;", cancellationToken, Parameter("$Id", id)); return await transaction.Session.QuerySingleOrDefaultAsync($"SELECT {PaymentColumns} FROM FinanceReceivablePayments WHERE Id=$Id;", ReadPayment, cancellationToken, Parameter("$Id", id)); }
