	internal Task<int> MarkPaymentReversedAsync(DatabaseTransactionContext transaction, FinanceReceivablePayment value, long expectedVersion, Guid reversalOperationId, long reversalJournalEntryId, DateTime reversedAtUtc, long userId, CancellationToken cancellationToken) => transaction.Session.ExecuteAsync("UPDATE FinanceReceivablePayments SET IsReversed=1,ReversalOperationId=$OperationId,ReversalJournalEntryId=$JournalEntryId,ReversedAtUtc=$At,ReversedByUserId=$UserId,Version=Version+1 WHERE Id=$Id AND Version=$ExpectedVersion AND IsReversed=0;", cancellationToken, Parameter("$OperationId", reversalOperationId.ToString("D")), Parameter("$JournalEntryId", reversalJournalEntryId), Parameter("$At", reversedAtUtc.ToString("O", CultureInfo.InvariantCulture)), Parameter("$UserId", userId), Parameter("$Id", value.Id), Parameter("$ExpectedVersion", expectedVersion));
	internal Task<FinanceReceivableWriteOff?> FindWriteOffByOperationAsync(DatabaseTransactionContext transaction, Guid operationId, CancellationToken cancellationToken) => transaction.Session.QuerySingleOrDefaultAsync($"SELECT {WriteOffColumns} FROM FinanceReceivableWriteOffs WHERE OperationId=$OperationId;", ReadWriteOff, cancellationToken, Parameter("$OperationId", operationId.ToString("D")));
	internal async Task<FinanceReceivableWriteOff?> LockWriteOffAsync(DatabaseTransactionContext transaction, long id, CancellationToken cancellationToken) { await transaction.Session.ExecuteAsync("UPDATE FinanceReceivableWriteOffs SET Version=Version WHERE Id=$Id;", cancellationToken, Parameter("$Id", id)); return await transaction.Session.QuerySingleOrDefaultAsync($"SELECT {WriteOffColumns} FROM FinanceReceivableWriteOffs WHERE Id=$Id;", ReadWriteOff, cancellationToken, Parameter("$Id", id)); }
