	internal async Task<FinanceDunningPolicy?> GetDunningPolicyAsync(DatabaseTransactionContext transaction, long id, CancellationToken cancellationToken) { var policy = await transaction.Session.QuerySingleOrDefaultAsync("SELECT Id,Version,LegalEntityId,Code,Name,IsActive FROM FinanceDunningPolicies WHERE Id=$Id;", ReadPolicy, cancellationToken, Parameter("$Id", id)); return policy is null ? null : policy with { Levels = await transaction.Session.QueryAsync("SELECT Id,PolicyId,LevelNumber,MinimumDaysOverdue,Code,Name FROM FinanceDunningPolicyLevels WHERE PolicyId=$Id ORDER BY LevelNumber;", ReadPolicyLevel, cancellationToken, Parameter("$Id", id)) }; }
	internal async Task<long> CreateDunningPolicyAsync(DatabaseTransactionContext transaction, FinanceDunningPolicy value, CancellationToken cancellationToken) { var id = await transaction.Session.InsertAsync("INSERT INTO FinanceDunningPolicies (Version,LegalEntityId,Code,Name,IsActive) VALUES (1,$LegalEntityId,$Code,$Name,$IsActive);", cancellationToken, Parameter("$LegalEntityId", value.LegalEntityId.ToString("D")), Parameter("$Code", value.Code), Parameter("$Name", value.Name), Parameter("$IsActive", value.IsActive)); await ReplaceDunningLevelsAsync(transaction, id, value.Levels, cancellationToken); return id; }
	internal async Task<int> UpdateDunningPolicyAsync(DatabaseTransactionContext transaction, FinanceDunningPolicy value, long expectedVersion, CancellationToken cancellationToken) { var changed = await transaction.Session.ExecuteAsync("UPDATE FinanceDunningPolicies SET Version=Version+1,LegalEntityId=$LegalEntityId,Code=$Code,Name=$Name,IsActive=$IsActive WHERE Id=$Id AND Version=$ExpectedVersion;", cancellationToken, Parameter("$LegalEntityId", value.LegalEntityId.ToString("D")), Parameter("$Code", value.Code), Parameter("$Name", value.Name), Parameter("$IsActive", value.IsActive), Parameter("$Id", value.Id), Parameter("$ExpectedVersion", expectedVersion)); if (changed == 0) return 0; await transaction.Session.ExecuteAsync("DELETE FROM FinanceDunningPolicyLevels WHERE PolicyId=$Id;", cancellationToken, Parameter("$Id", value.Id)); await ReplaceDunningLevelsAsync(transaction, value.Id, value.Levels, cancellationToken); return changed; }
	internal Task<FinanceDunningRun?> FindDunningRunByOperationAsync(DatabaseTransactionContext transaction, Guid operationId, CancellationToken cancellationToken) => transaction.Session.QuerySingleOrDefaultAsync("SELECT Id,OperationId,RequestHash,PolicyId,AsOfDate,CreatedAtUtc,CreatedByUserId FROM FinanceDunningRuns WHERE OperationId=$OperationId;", ReadDunningRun, cancellationToken, Parameter("$OperationId", operationId.ToString("D")));
	internal async Task<long> CreateDunningRunAsync(DatabaseTransactionContext transaction, FinanceDunningRun value, CancellationToken cancellationToken) { var id = await transaction.Session.InsertAsync("INSERT INTO FinanceDunningRuns (OperationId,RequestHash,PolicyId,AsOfDate,CreatedAtUtc,CreatedByUserId) VALUES ($OperationId,$RequestHash,$PolicyId,$AsOfDate,$CreatedAtUtc,$CreatedByUserId);", cancellationToken, Parameter("$OperationId", value.OperationId.ToString("D")), Parameter("$RequestHash", value.RequestHash), Parameter("$PolicyId", value.PolicyId), Parameter("$AsOfDate", value.AsOfDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)), Parameter("$CreatedAtUtc", value.CreatedAtUtc.ToString("O", CultureInfo.InvariantCulture)), Parameter("$CreatedByUserId", value.CreatedByUserId)); foreach (var line in value.Lines) await transaction.Session.ExecuteAsync("INSERT INTO FinanceDunningRunLines (RunId,OpenItemId,CustomerId,CurrencyCode,OutstandingAmount,DaysOverdue,LevelNumber,LevelCode) VALUES ($RunId,$OpenItemId,$CustomerId,$Currency,$Outstanding,$Days,$LevelNumber,$LevelCode);", cancellationToken, Parameter("$RunId", id), Parameter("$OpenItemId", line.OpenItemId), Parameter("$CustomerId", line.CustomerId), Parameter("$Currency", line.Currency.Value), Parameter("$Outstanding", line.OutstandingAmount), Parameter("$Days", line.DaysOverdue), Parameter("$LevelNumber", line.LevelNumber), Parameter("$LevelCode", line.LevelCode)); return id; }
	internal Task<IReadOnlyList<FinanceReceivableOpenItem>> GetDunningCandidatesAsync(DatabaseTransactionContext transaction, Guid legalEntityId, DateOnly asOfDate, CancellationToken cancellationToken) => transaction.Session.QueryAsync($"SELECT {OpenItemColumns} FROM FinanceReceivableOpenItems oi INNER JOIN Customers c ON c.Id=oi.CustomerId WHERE oi.LegalEntityId=$LegalEntityId AND oi.Kind=1 AND oi.IsVoided=0 AND oi.RemainingAmount>0 AND oi.DueDate<$AsOfDate ORDER BY oi.DueDate,oi.Id;", ReadOpenItem, cancellationToken, Parameter("$LegalEntityId", legalEntityId.ToString("D")), Parameter("$AsOfDate", asOfDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)));

	private static async Task ReplaceDunningLevelsAsync(DatabaseTransactionContext transaction, long policyId, IReadOnlyList<FinanceDunningLevel> levels, CancellationToken cancellationToken) { foreach (var level in levels.OrderBy(value => value.LevelNumber)) await transaction.Session.ExecuteAsync("INSERT INTO FinanceDunningPolicyLevels (PolicyId,LevelNumber,MinimumDaysOverdue,Code,Name) VALUES ($PolicyId,$LevelNumber,$MinimumDays,$Code,$Name);", cancellationToken, Parameter("$PolicyId", policyId), Parameter("$LevelNumber", level.LevelNumber), Parameter("$MinimumDays", level.MinimumDaysOverdue), Parameter("$Code", level.Code), Parameter("$Name", level.Name)); }
	private Task<IReadOnlyList<FinanceDunningLevel>> LoadPolicyLevelsAsync(long policyId, CancellationToken cancellationToken) => Database.QueryAsync("SELECT Id,PolicyId,LevelNumber,MinimumDaysOverdue,Code,Name FROM FinanceDunningPolicyLevels WHERE PolicyId=$Id ORDER BY LevelNumber;", ReadPolicyLevel, cancellationToken, Parameter("$Id", policyId));
	private Task<IReadOnlyList<FinanceDunningRunLine>> LoadRunLinesAsync(long runId, CancellationToken cancellationToken) => Database.QueryAsync("SELECT l.Id,l.RunId,l.OpenItemId,l.CustomerId,c.Name,l.CurrencyCode,l.OutstandingAmount,l.DaysOverdue,l.LevelNumber,l.LevelCode FROM FinanceDunningRunLines l INNER JOIN Customers c ON c.Id=l.CustomerId WHERE l.RunId=$RunId ORDER BY c.Name,l.CurrencyCode,l.OpenItemId;", ReadRunLine, cancellationToken, Parameter("$RunId", runId));
